insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welches Lager ist hier im Schnitt dargestellt?$q$, $q$Which bearing is shown here in section?$q$, $q$img/lager_rillenkugellager.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Schrägkugellager|angular contact ball bearing}}", "en": "{{angular contact ball bearing|Schrägkugellager}}"}, {"de": "{{Rillenkugellager|deep groove ball bearing}}", "en": "{{deep groove ball bearing|Rillenkugellager}}"}, {"de": "{{Pendelkugellager|self-aligning ball bearing}}", "en": "{{self-aligning ball bearing|Pendelkugellager}}"}, {"de": "{{Vierpunktlager|four-point contact bearing}}", "en": "{{four-point contact bearing|Vierpunktlager}}"}]$q$::jsonb, $q$1$q$::jsonb, $q$Ein {{Rillenkugellager|deep groove ball bearing}}: eine Kugelreihe, die in rillenförmigen Laufbahnen beider Ringe läuft. Häufigstes und günstigstes Radiallager.$q$, $q$A {{deep groove ball bearing|Rillenkugellager}}: one row of balls running in groove-shaped raceways in both rings. The most common and cheapest radial bearing.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welches Lager ist hier im Schnitt dargestellt?$q$, $q$Which bearing is shown here in section?$q$, $q$img/lager_schraegkugellager.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Rillenkugellager|deep groove ball bearing}}", "en": "{{deep groove ball bearing|Rillenkugellager}}"}, {"de": "{{Axial-Rillenkugellager|axial deep groove ball bearing}}", "en": "{{axial deep groove ball bearing|Axial-Rillenkugellager}}"}, {"de": "{{Schrägkugellager|angular contact ball bearing}}", "en": "{{angular contact ball bearing|Schrägkugellager}}"}, {"de": "{{Pendelkugellager|self-aligning ball bearing}}", "en": "{{self-aligning ball bearing|Pendelkugellager}}"}]$q$::jsonb, $q$2$q$::jsonb, $q$Ein {{Schrägkugellager|angular contact ball bearing}}: Die Ringe haben je eine hohe und eine niedrige Schulter, die Kugeln laufen schräg (Druckwinkel α). Es nimmt Axialkraft nur in einer Richtung auf.$q$, $q$An {{angular contact ball bearing|Schrägkugellager}}: each ring has one high and one low shoulder, so the balls run at an angle (contact angle α). It takes axial force in one direction only.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welches Lager ist hier im Schnitt dargestellt?$q$, $q$Which bearing is shown here in section?$q$, $q$img/lager_pendelkugellager.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Pendelkugellager|self-aligning ball bearing}}", "en": "{{self-aligning ball bearing|Pendelkugellager}}"}, {"de": "{{Pendelrollenlager|spherical roller bearing}}", "en": "{{spherical roller bearing|Pendelrollenlager}}"}, {"de": "{{Rillenkugellager|deep groove ball bearing}}", "en": "{{deep groove ball bearing|Rillenkugellager}}"}, {"de": "{{Schrägkugellager|angular contact ball bearing}}", "en": "{{angular contact ball bearing|Schrägkugellager}}"}]$q$::jsonb, $q$0$q$::jsonb, $q$Ein {{Pendelkugellager|self-aligning ball bearing}}: zwei Kugelreihen und eine hohlkugelige Laufbahn im Außenring. Dadurch gleicht es {{Fluchtungsfehler|misalignment}} bis ca. 4° aus.$q$, $q$A {{self-aligning ball bearing|Pendelkugellager}}: two rows of balls and a hollow-spherical raceway in the outer ring. This lets it compensate {{misalignment|Fluchtungsfehler}} of up to approx. 4°.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welches Lager ist hier im Schnitt dargestellt?$q$, $q$Which bearing is shown here in section?$q$, $q$img/lager_zylinderrollenlager.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Nadellager|needle roller bearing}}", "en": "{{needle roller bearing|Nadellager}}"}, {"de": "{{Kegelrollenlager|tapered roller bearing}}", "en": "{{tapered roller bearing|Kegelrollenlager}}"}, {"de": "{{Zylinderrollenlager|cylindrical roller bearing}}", "en": "{{cylindrical roller bearing|Zylinderrollenlager}}"}, {"de": "{{Tonnenlager|barrel bearing}}", "en": "{{barrel bearing|Tonnenlager}}"}]$q$::jsonb, $q$2$q$::jsonb, $q$Ein {{Zylinderrollenlager|cylindrical roller bearing}} (Bauform NU): Die zylindrischen Rollen werden von Borden am Außenring geführt, der Innenring hat keine Borde. So ist es als {{Loslager|non-locating bearing}} einsetzbar.$q$, $q$A {{cylindrical roller bearing|Zylinderrollenlager}} (design NU): the cylindrical rollers are guided by ribs on the outer ring and the inner ring has no ribs. This makes it usable as a {{non-locating bearing|Loslager}}.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welches Lager ist hier im Schnitt dargestellt?$q$, $q$Which bearing is shown here in section?$q$, $q$img/lager_kegelrollenlager.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Zylinderrollenlager|cylindrical roller bearing}}", "en": "{{cylindrical roller bearing|Zylinderrollenlager}}"}, {"de": "{{Kegelrollenlager|tapered roller bearing}}", "en": "{{tapered roller bearing|Kegelrollenlager}}"}, {"de": "{{Schrägkugellager|angular contact ball bearing}}", "en": "{{angular contact ball bearing|Schrägkugellager}}"}, {"de": "{{Pendelrollenlager|spherical roller bearing}}", "en": "{{spherical roller bearing|Pendelrollenlager}}"}]$q$::jsonb, $q$1$q$::jsonb, $q$Ein {{Kegelrollenlager|tapered roller bearing}}: kegelige Rollen und kegelige Laufbahnen; der Außenring ist abnehmbar. Es trägt hohe Radialkräfte und Axialkräfte in einer Richtung und wird meist paarweise in O- oder X-Anordnung eingebaut.$q$, $q$A {{tapered roller bearing|Kegelrollenlager}}: tapered rollers and conical raceways; the outer ring is removable. It carries high radial forces and axial forces in one direction, and is usually mounted in pairs in O or X arrangement.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welches Lager ist hier im Schnitt dargestellt?$q$, $q$Which bearing is shown here in section?$q$, $q$img/lager_nadellager.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Zylinderrollenlager|cylindrical roller bearing}}", "en": "{{cylindrical roller bearing|Zylinderrollenlager}}"}, {"de": "{{Nadellager|needle roller bearing}}", "en": "{{needle roller bearing|Nadellager}}"}, {"de": "{{Rillenkugellager|deep groove ball bearing}}", "en": "{{deep groove ball bearing|Rillenkugellager}}"}, {"de": "{{Axial-Zylinderrollenlager|axial cylindrical roller bearing}}", "en": "{{axial cylindrical roller bearing|Axial-Zylinderrollenlager}}"}]$q$::jsonb, $q$1$q$::jsonb, $q$Ein {{Nadellager|needle roller bearing}}: sehr dünne, lange Rollen (Durchmesser ≤ 5 mm, Länge ≥ 2,5 · d). Es ist sehr kompakt, braucht wenig radialen Bauraum und nimmt nur Radialkräfte auf.$q$, $q$A {{needle roller bearing|Nadellager}}: very thin, long rollers (diameter ≤ 5 mm, length ≥ 2.5 · d). It is very compact, needs little radial space and carries radial forces only.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welches Lager ist hier im Schnitt dargestellt?$q$, $q$Which bearing is shown here in section?$q$, $q$img/lager_pendelrollenlager.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Pendelkugellager|self-aligning ball bearing}}", "en": "{{self-aligning ball bearing|Pendelkugellager}}"}, {"de": "{{Tonnenlager|barrel bearing}}", "en": "{{barrel bearing|Tonnenlager}}"}, {"de": "{{Pendelrollenlager|spherical roller bearing}}", "en": "{{spherical roller bearing|Pendelrollenlager}}"}, {"de": "{{Kegelrollenlager|tapered roller bearing}}", "en": "{{tapered roller bearing|Kegelrollenlager}}"}]$q$::jsonb, $q$2$q$::jsonb, $q$Ein {{Pendelrollenlager|spherical roller bearing}}: zwei Reihen tonnenförmiger Rollen in einer hohlkugeligen Außenringlaufbahn. Es ist radial und axial hoch belastbar und gleicht Schiefstellungen bis ca. 0,5° aus (bis 2° bei geringer Last).$q$, $q$A {{spherical roller bearing|Pendelrollenlager}}: two rows of barrel-shaped rollers in a hollow-spherical outer ring raceway. It takes high radial and axial loads and compensates misalignment of approx. 0.5° (up to 2° at low load).$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welches Lager ist hier im Schnitt dargestellt?$q$, $q$Which bearing is shown here in section?$q$, $q$img/lager_axialrillenkugellager.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Rillenkugellager|deep groove ball bearing}}", "en": "{{deep groove ball bearing|Rillenkugellager}}"}, {"de": "{{Schrägkugellager|angular contact ball bearing}}", "en": "{{angular contact ball bearing|Schrägkugellager}}"}, {"de": "{{Axial-Rillenkugellager|axial deep groove ball bearing}}", "en": "{{axial deep groove ball bearing|Axial-Rillenkugellager}}"}, {"de": "{{Axial-Zylinderrollenlager|axial cylindrical roller bearing}}", "en": "{{axial cylindrical roller bearing|Axial-Zylinderrollenlager}}"}]$q$::jsonb, $q$2$q$::jsonb, $q$Ein {{Axial-Rillenkugellager|axial deep groove ball bearing}}: Die Kugeln laufen zwischen einer Wellenscheibe und einer Gehäusescheibe. Es ist axial hoch belastbar, aber kaum radial.$q$, $q$An {{axial deep groove ball bearing|Axial-Rillenkugellager}}: the balls run between a shaft washer and a housing washer. It takes high axial loads but hardly any radial load.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welche Lageranordnung ist dargestellt? (gestrichelt: {{Drucklinien|pressure lines}})$q$, $q$Which bearing arrangement is shown? (dashed: {{pressure lines|Drucklinien}})$q$, $q$img/lagerung_o.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{O-Anordnung|O-arrangement}}", "en": "{{O-arrangement|O-Anordnung}}"}, {"de": "{{X-Anordnung|X-arrangement}}", "en": "{{X-arrangement|X-Anordnung}}"}, {"de": "{{Fest-Los-Lagerung|locating/non-locating bearing arrangement}}", "en": "{{locating/non-locating bearing arrangement|Fest-Los-Lagerung}}"}, {"de": "{{schwimmende Lagerung|floating bearing arrangement}}", "en": "{{floating bearing arrangement|schwimmende Lagerung}}"}]$q$::jsonb, $q$0$q$::jsonb, $q${{O-Anordnung|O-arrangement}}: Die {{Drucklinien|pressure lines}} zeigen nach außen und schneiden die Achse außerhalb der Lager. Das ergibt eine große {{Stützbasis|support distance}} und eine hohe Kippsteifigkeit.$q$, $q${{O-arrangement|O-Anordnung}}: the {{pressure lines|Drucklinien}} point outwards and meet the axis outside the bearings. This gives a large {{support distance|Stützbasis}} and high tilting stiffness.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$img$q$, $q$Welche Lageranordnung ist dargestellt? (gestrichelt: {{Drucklinien|pressure lines}})$q$, $q$Which bearing arrangement is shown? (dashed: {{pressure lines|Drucklinien}})$q$, $q$img/lagerung_x.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{O-Anordnung|O-arrangement}}", "en": "{{O-arrangement|O-Anordnung}}"}, {"de": "{{X-Anordnung|X-arrangement}}", "en": "{{X-arrangement|X-Anordnung}}"}, {"de": "{{Fest-Los-Lagerung|locating/non-locating bearing arrangement}}", "en": "{{locating/non-locating bearing arrangement|Fest-Los-Lagerung}}"}, {"de": "{{schwimmende Lagerung|floating bearing arrangement}}", "en": "{{floating bearing arrangement|schwimmende Lagerung}}"}]$q$::jsonb, $q$1$q$::jsonb, $q${{X-Anordnung|X-arrangement}}: Die {{Drucklinien|pressure lines}} zeigen nach innen und schneiden sich zwischen den Lagern. Die {{Stützbasis|support distance}} ist kleiner, dafür lässt die Anordnung mehr Winkelfehler zu.$q$, $q${{X-arrangement|X-Anordnung}}: the {{pressure lines|Drucklinien}} point inwards and cross between the bearings. The {{support distance|Stützbasis}} is smaller, but the arrangement tolerates more angular error.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Welches ist das am häufigsten verwendete und kostengünstigste Radial-Wälzlager?$q$, $q$Which is the most commonly used and most cost-effective radial rolling bearing?$q$, null, null, $q$[{"de": "{{Zylinderrollenlager|cylindrical roller bearing}}", "en": "{{cylindrical roller bearing|Zylinderrollenlager}}"}, {"de": "{{Rillenkugellager|deep groove ball bearing}}", "en": "{{deep groove ball bearing|Rillenkugellager}}"}, {"de": "{{Kegelrollenlager|tapered roller bearing}}", "en": "{{tapered roller bearing|Kegelrollenlager}}"}, {"de": "{{Nadellager|needle roller bearing}}", "en": "{{needle roller bearing|Nadellager}}"}]$q$::jsonb, $q$1$q$::jsonb, $q$Das {{Rillenkugellager|deep groove ball bearing}} ist das universelle Standardlager. Es nimmt Radial- und Axialkräfte in beiden Richtungen auf und eignet sich als {{Festlager|locating bearing}}.$q$, $q$The {{deep groove ball bearing|Rillenkugellager}} is the universal standard bearing. It takes radial and axial forces in both directions and is suitable as a {{locating bearing|Festlager}}.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Eine lange Welle biegt sich stark durch, die Lagerstellen fluchten nicht. Welches Lager gleicht Schiefstellungen bis ca. 4° aus?$q$, $q$A long shaft deflects considerably and the bearing seats are misaligned. Which bearing compensates misalignment of up to approx. 4°?$q$, null, null, $q$[{"de": "{{Pendelkugellager|self-aligning ball bearing}}", "en": "{{self-aligning ball bearing|Pendelkugellager}}"}, {"de": "{{Zylinderrollenlager|cylindrical roller bearing}}", "en": "{{cylindrical roller bearing|Zylinderrollenlager}}"}, {"de": "{{Kegelrollenlager|tapered roller bearing}}", "en": "{{tapered roller bearing|Kegelrollenlager}}"}, {"de": "{{Nadellager|needle roller bearing}}", "en": "{{needle roller bearing|Nadellager}}"}]$q$::jsonb, $q$0$q$::jsonb, $q$Das {{Pendelkugellager|self-aligning ball bearing}} ist durch die hohlkugelige Außenringlaufbahn winkeleinstellbar. {{Zylinderrollenlager|cylindrical roller bearing}} und {{Kegelrollenlager|tapered roller bearing}} reagieren dagegen sehr empfindlich auf {{Fluchtungsfehler|misalignment}}.$q$, $q$The {{self-aligning ball bearing|Pendelkugellager}} is self-aligning thanks to its hollow-spherical outer ring raceway. {{Cylindrical roller bearing|Zylinderrollenlager}} and {{tapered roller bearing|Kegelrollenlager}} are very sensitive to {{misalignment|Fluchtungsfehler}}.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Was gibt das Kurzzeichen eines Wälzlagers (z. B. 6205) nach DIN 623 an?$q$, $q$What does the designation of a rolling bearing (e.g. 6205) indicate according to DIN 623?$q$, null, null, $q$[{"de": "Lagerart, Maßreihe und Bohrungsdurchmesser (codiert)", "en": "Bearing type, dimension series and bore diameter (coded)"}, {"de": "Hersteller und Herstellungsjahr", "en": "Manufacturer and year of production"}, {"de": "Zulässige Drehzahl und Lebensdauer", "en": "Permissible speed and service life"}, {"de": "Werkstoff und Härte der Wälzkörper", "en": "Material and hardness of the rolling elements"}]$q$::jsonb, $q$0$q$::jsonb, $q$Das Basiszeichen enthält codiert Lagerart, Maßreihe und Bohrungsdurchmesser. Vorsetz- und Nachsetzzeichen kennzeichnen Einzelteile oder Abweichungen vom Standard.$q$, $q$The basic designation contains the bearing type, dimension series and bore diameter in coded form. Prefixes and suffixes identify individual parts or deviations from the standard.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Was ist ein wesentlicher Vorteil von {{Wälzlager|rolling bearing}}n gegenüber {{Gleitlager|plain bearing}}n?$q$, $q$What is a key advantage of {{rolling bearing|Wälzlager}}s over {{plain bearing|Gleitlager}}s?$q$, null, null, $q$[{"de": "International genormt und dadurch leicht austauschbar", "en": "Internationally standardized and therefore easily interchangeable"}, {"de": "Unempfindlich gegen Stöße", "en": "Insensitive to shocks"}, {"de": "Leiserer Lauf bei hohen Drehzahlen", "en": "Quieter running at high speeds"}, {"de": "Höhere Grenzdrehzahl", "en": "Higher speed limit"}]$q$::jsonb, $q$0$q$::jsonb, $q$Wälzlager sind genormte Massenprodukte: Ein Lager mit gleichem Kurzzeichen passt herstellerübergreifend. Außerdem haben sie meist weniger Reibung und brauchen wenig Wartung. Stoßempfindlichkeit, Geräusche und die niedrigere Grenzdrehzahl sind dagegen Nachteile.$q$, $q$Rolling bearings are standardized mass products: a bearing with the same designation fits regardless of manufacturer. They also usually have lower friction and need little maintenance. Sensitivity to shocks, noise and the lower speed limit are disadvantages.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$tf$q$, $q$Ein {{Loslager|non-locating bearing}} nimmt nur Radialkräfte auf.$q$, $q$A {{non-locating bearing|Loslager}} absorbs radial forces only.$q$, null, null, null, $q$true$q$::jsonb, $q$Richtig. Das {{Loslager|non-locating bearing}} ist axial verschiebbar und gleicht so Wärmedehnungen aus. Die Axialkräfte nimmt allein das {{Festlager|locating bearing}} auf.$q$, $q$Correct. The {{non-locating bearing|Loslager}} can move axially to compensate thermal expansion. Axial forces are taken by the {{locating bearing|Festlager}} alone.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$tf$q$, $q${{Nadellager|needle roller bearing}} können hohe Axialkräfte aufnehmen.$q$, $q${{Needle roller bearing|Nadellager}}s can absorb high axial forces.$q$, null, null, null, $q$false$q$::jsonb, $q$Falsch. {{Nadellager|needle roller bearing}} nehmen nur Radialkräfte auf. Ihr Vorteil ist der sehr geringe radiale Bauraum bei hoher Steifigkeit.$q$, $q$False. {{Needle roller bearing|Nadellager}}s carry radial forces only. Their advantage is very little radial installation space with high stiffness.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Welchen Wert hat der {{Lebensdauerexponent|life exponent}} p für Kugellager?$q$, $q$What is the value of the {{life exponent|Lebensdauerexponent}} p for ball bearings?$q$, null, null, $q$[{"de": "p = 3", "en": "p = 3"}, {"de": "p = 10/3", "en": "p = 10/3"}, {"de": "p = 2", "en": "p = 2"}, {"de": "p = 1/3", "en": "p = 1/3"}]$q$::jsonb, $q$0$q$::jsonb, $q$Kugellager haben {{Punktberührung|point contact}}, daher p = 3. Rollenlager haben {{Linienberührung|line contact}}, daher p = 10/3. Es gilt L10 = (C/P)^p · 10⁶ Umdrehungen.$q$, $q$Ball bearings have {{point contact|Punktberührung}}, so p = 3. Roller bearings have {{line contact|Linienberührung}}, so p = 10/3. L10 = (C/P)^p · 10⁶ revolutions.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$tf$q$, $q$Die {{nominelle Lebensdauer|nominal service life}} L10 wird von 90 % einer Gruppe gleicher Lager erreicht oder überschritten.$q$, $q$The {{nominal service life|nominelle Lebensdauer}} L10 is reached or exceeded by 90 % of a group of identical bearings.$q$, null, null, null, $q$true$q$::jsonb, $q$Richtig. L10 entspricht 90 % Erlebenswahrscheinlichkeit, also 10 % Ausfallwahrscheinlichkeit. Lebensdauerangaben sind statistische Aussagen.$q$, $q$Correct. L10 corresponds to 90 % survival probability, i.e. 10 % failure probability. Service life values are statistical statements.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Was bedeutet das Nachsetzzeichen 2RS bei einem {{Rillenkugellager|deep groove ball bearing}}?$q$, $q$What does the suffix 2RS mean for a {{deep groove ball bearing|Rillenkugellager}}?$q$, null, null, $q$[{"de": "{{Deckscheibe|shield}} auf beiden Seiten", "en": "{{Shield|Deckscheibe}}s on both sides"}, {"de": "{{Dichtung|seal}}en auf beiden Seiten", "en": "{{Seal|Dichtung}}s on both sides"}, {"de": "{{Lagerluft|bearing clearance}} größer als normal", "en": "{{Bearing clearance|Lagerluft}} larger than normal"}, {"de": "Toleranz enger als normal", "en": "Tolerance tighter than normal"}]$q$::jsonb, $q$1$q$::jsonb, $q$2RS steht für berührende Dichtungen auf beiden Seiten. Z bzw. 2Z bezeichnet Deckscheiben (Spaltabdichtung). Gedichtete Lager sind meist auf Lebensdauer gefettet.$q$, $q$2RS means contact seals on both sides. Z or 2Z denotes shields (gap seal). Sealed bearings are usually greased for life.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Die {{Lagerluft|bearing clearance}} wird im Betrieb durch Wärmedehnung oder einen festen Sitz kleiner. Was kann passieren, wenn sie ganz verschwindet?$q$, $q$In operation the {{bearing clearance|Lagerluft}} is reduced by thermal expansion or a tight fit. What can happen if it disappears completely?$q$, null, null, $q$[{"de": "Das Lager kann klemmen (verspannen)", "en": "The bearing can jam"}, {"de": "Das Lager läuft dadurch leiser und länger", "en": "The bearing runs quieter and longer"}, {"de": "Die Wälzkörper fallen heraus", "en": "The rolling elements fall out"}, {"de": "Nichts – Lagerluft ist nur für die Montage wichtig", "en": "Nothing – clearance only matters for mounting"}]$q$::jsonb, $q$0$q$::jsonb, $q$Ohne Restluft verspannen sich Ringe und Wälzkörper: Reibung und Temperatur steigen, das Lager kann klemmen. Abhilfe ist eine größere Luftklasse (z. B. C3).$q$, $q$Without remaining clearance the rings and rolling elements are preloaded: friction and temperature rise and the bearing can jam. The remedy is a larger clearance class (e.g. C3).$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$match$q$, $q$Ordne jedem Lager die passende Eigenschaft zu.$q$, $q$Match each bearing to its typical property.$q$, null, null, $q${"left": [{"de": "{{Rillenkugellager|deep groove ball bearing}}", "en": "{{deep groove ball bearing|Rillenkugellager}}"}, {"de": "{{Zylinderrollenlager|cylindrical roller bearing}} NU", "en": "{{cylindrical roller bearing|Zylinderrollenlager}} NU"}, {"de": "{{Pendelkugellager|self-aligning ball bearing}}", "en": "{{self-aligning ball bearing|Pendelkugellager}}"}, {"de": "{{Kegelrollenlager|tapered roller bearing}}", "en": "{{tapered roller bearing|Kegelrollenlager}}"}, {"de": "{{Nadellager|needle roller bearing}}", "en": "{{needle roller bearing|Nadellager}}"}], "right": [{"de": "Universallager, radial + axial in beide Richtungen", "en": "Universal bearing, radial + axial in both directions"}, {"de": "{{Loslager|non-locating bearing}} mit Verschiebung im Lager", "en": "{{Non-locating bearing|Loslager}} with displacement inside the bearing"}, {"de": "Gleicht große Schiefstellungen aus", "en": "Compensates large misalignment"}, {"de": "Paarweise in O- oder X-Anordnung", "en": "Mounted in pairs in O or X arrangement"}, {"de": "Sehr kleiner radialer Bauraum", "en": "Very small radial installation space"}]}$q$::jsonb, null, $q$Typische Einsatzfälle laut Skript: {{Rillenkugellager|deep groove ball bearing}} = universell; {{Zylinderrollenlager|cylindrical roller bearing}} NU = Loslager; {{Pendelkugellager|self-aligning ball bearing}} = Winkelausgleich; {{Kegelrollenlager|tapered roller bearing}} = angestellte Lagerung; {{Nadellager|needle roller bearing}} = wenig Bauraum.$q$, $q$Typical uses according to the lecture: {{deep groove ball bearing|Rillenkugellager}} = universal; {{cylindrical roller bearing|Zylinderrollenlager}} NU = non-locating bearing; {{self-aligning ball bearing|Pendelkugellager}} = misalignment compensation; {{tapered roller bearing|Kegelrollenlager}} = adjusted arrangement; {{needle roller bearing|Nadellager}} = little installation space.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$In einer {{Fest-Los-Lagerung|locating/non-locating bearing arrangement}} soll sich die Welle bei Erwärmung im Loslager selbst verschieben können, ohne Schiebesitz. Welches Lager eignet sich?$q$, $q$In a {{locating/non-locating bearing arrangement|Fest-Los-Lagerung}} the shaft should be able to move inside the non-locating bearing itself when heated, without a sliding fit. Which bearing is suitable?$q$, null, null, $q$[{"de": "{{Rillenkugellager|deep groove ball bearing}}", "en": "{{deep groove ball bearing|Rillenkugellager}}"}, {"de": "{{Zylinderrollenlager|cylindrical roller bearing}} NU", "en": "{{cylindrical roller bearing|Zylinderrollenlager}} NU"}, {"de": "{{Schrägkugellager|angular contact ball bearing}}", "en": "{{angular contact ball bearing|Schrägkugellager}}"}, {"de": "{{Axial-Rillenkugellager|axial deep groove ball bearing}}", "en": "{{axial deep groove ball bearing|Axial-Rillenkugellager}}"}]$q$::jsonb, $q$1$q$::jsonb, $q$Beim {{Zylinderrollenlager|cylindrical roller bearing}} NU (bordloser Innenring) erfolgt die Verschiebung zwischen Rollen und Laufbahn. Beim {{Rillenkugellager|deep groove ball bearing}} als Loslager muss dagegen ein Ring in seinem Sitz verschiebbar sein.$q$, $q$In the {{cylindrical roller bearing|Zylinderrollenlager}} NU (ribless inner ring) the displacement takes place between rollers and raceway. A {{deep groove ball bearing|Rillenkugellager}} used as non-locating bearing instead needs one ring to slide in its seat.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$tf$q$, $q$Ein Lagerring mit {{Umfangslast|circumferential load}} braucht einen festen Sitz (Presspassung).$q$, $q$A bearing ring subjected to {{circumferential load|Umfangslast}} needs a tight fit (interference fit).$q$, null, null, null, $q$true$q$::jsonb, $q$Richtig. Bei Umfangslast würde ein loser Ring „wandern“ und {{Passungsrost|fretting corrosion}} verursachen. Bei Punktlast ist ein loser Sitz zulässig.$q$, $q$Correct. Under circumferential load a loose ring would 'creep' and cause {{fretting corrosion|Passungsrost}}. Under point load a loose fit is permissible.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Welche Aufgabe hat der {{Käfig|cage}} im Wälzlager?$q$, $q$What is the task of the {{cage|Käfig}} in a rolling bearing?$q$, null, null, $q$[{"de": "Er überträgt die Radialkraft auf den Außenring", "en": "It transmits the radial force to the outer ring"}, {"de": "Er führt die {{Wälzkörper|rolling element}} und hält sie auf Abstand", "en": "It guides the {{rolling element|Wälzkörper}}s and keeps them spaced apart"}, {"de": "Er dichtet das Lager nach außen ab", "en": "It seals the bearing from the outside"}, {"de": "Er erhöht die Lagerluft", "en": "It increases the bearing clearance"}]$q$::jsonb, $q$1$q$::jsonb, $q$Der Käfig führt die Wälzkörper und hält sie auf Abstand. Außerdem speichert und verteilt er Schmierfett und dämpft Schwingungen. Er überträgt keine Lagerkraft.$q$, $q$The cage guides the rolling elements and keeps them spaced apart. It also stores and distributes grease and damps vibrations. It does not transmit bearing loads.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$tf$q$, $q${{Wälzlager|rolling bearing}} sind stoßunempfindlicher als hydrodynamische {{Gleitlager|plain bearing}}.$q$, $q${{Rolling bearing|Wälzlager}}s are less sensitive to shocks than hydrodynamic {{plain bearing|Gleitlager}}s.$q$, null, null, null, $q$false$q$::jsonb, $q$Falsch. Wälzlager sind stoßempfindlich, besonders im Stillstand und bei niedriger Drehzahl. Hydrodynamische Gleitlager dämpfen gut.$q$, $q$False. Rolling bearings are sensitive to shocks, especially at standstill and low speed. Hydrodynamic plain bearings have good damping.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Wann wird ein Wälzlager nach der {{statische Tragzahl C0|static load rating C0}} ausgelegt?$q$, $q$When is a rolling bearing designed using the {{static load rating C0|statische Tragzahl C0}}?$q$, null, null, $q$[{"de": "Bei hohen Drehzahlen", "en": "At high speeds"}, {"de": "Im Stillstand, bei n < 10 min⁻¹ oder langsamen Schwenkbewegungen", "en": "At standstill, at n < 10 rpm or slow oscillating motion"}, {"de": "Nur bei reiner Axiallast", "en": "Only under pure axial load"}, {"de": "Immer, wenn die Last schwankt", "en": "Whenever the load fluctuates"}]$q$::jsonb, $q$1$q$::jsonb, $q$Statische Beanspruchung liegt vor, wenn sich das Lager unter Last nicht (oder kaum) dreht. Maßgebend sind dann plastische Eindrückungen. Statisch/dynamisch bezieht sich auf die Drehung, nicht auf den zeitlichen Lastverlauf.$q$, $q$Static stress applies when the bearing does not rotate (or barely rotates) under load. Plastic indentation is then decisive. Static/dynamic refers to rotation, not to how the load changes over time.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$tf$q$, $q$Die {{O-Anordnung|O-arrangement}} hat eine größere {{Stützbasis|support distance}} und ist kippsteifer als die {{X-Anordnung|X-arrangement}}.$q$, $q$The {{O-arrangement|O-Anordnung}} has a larger {{support distance|Stützbasis}} and is stiffer against tilting than the {{X-arrangement|X-Anordnung}}.$q$, null, null, null, $q$true$q$::jsonb, $q$Richtig. In der O-Anordnung zeigen die Drucklinien nach außen, die Stützbasis wird größer. Die X-Anordnung ist weniger steif, lässt aber mehr Winkelfehler zu.$q$, $q$Correct. In the O-arrangement the pressure lines point outwards, which enlarges the support distance. The X-arrangement is less stiff but tolerates more angular error.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$match$q$, $q$Ordne die Kurzzeichen ihrer Bedeutung zu.$q$, $q$Match the designation codes to their meaning.$q$, null, null, $q${"left": [{"de": "K", "en": "K"}, {"de": "S", "en": "S"}, {"de": "C3", "en": "C3"}, {"de": "P5", "en": "P5"}, {"de": "Z", "en": "Z"}], "right": [{"de": "Käfig mit Wälzkörpern", "en": "Cage with rolling elements"}, {"de": "Nichtrostender Stahl", "en": "Stainless steel"}, {"de": "{{Lagerluft|bearing clearance}} größer als normal", "en": "{{Bearing clearance|Lagerluft}} larger than normal"}, {"de": "Toleranz enger als normal", "en": "Tolerance tighter than normal"}, {"de": "Eine {{Deckscheibe|shield}}", "en": "One {{shield|Deckscheibe}}"}]}$q$::jsonb, null, $q$Vorsetzzeichen (K, L, R, S) kennzeichnen Einzelteile oder den Werkstoff. Nachsetzzeichen (C2, C3, P5, MA, RS, Z …) kennzeichnen Abweichungen von der Standardausführung (DIN 623).$q$, $q$Prefixes (K, L, R, S) identify individual parts or the material. Suffixes (C2, C3, P5, MA, RS, Z …) identify deviations from the standard design (DIN 623).$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Welche Lagerung ist am einfachsten und günstigsten, legt die Welle axial aber nicht genau fest (sie „schwimmt“)?$q$, $q$Which arrangement is the simplest and cheapest, but does not define the shaft position exactly (the shaft 'floats')?$q$, null, null, $q$[{"de": "{{Fest-Los-Lagerung|locating/non-locating bearing arrangement}}", "en": "{{locating/non-locating bearing arrangement|Fest-Los-Lagerung}}"}, {"de": "{{schwimmende Lagerung|floating bearing arrangement}}", "en": "{{floating bearing arrangement|schwimmende Lagerung}}"}, {"de": "{{angestellte Lagerung|adjusted bearing arrangement}} in O", "en": "{{adjusted bearing arrangement|angestellte Lagerung}} in O"}, {"de": "{{angestellte Lagerung|adjusted bearing arrangement}} in X", "en": "{{adjusted bearing arrangement|angestellte Lagerung}} in X"}]$q$::jsonb, $q$1$q$::jsonb, $q$Bei der {{schwimmende Lagerung|floating bearing arrangement}} hat die Welle ein definiertes Axialspiel von ca. 0,5 … 1 mm. Sie ist einfach und günstig, aber nicht für wechselnde Axialkräfte geeignet.$q$, $q$In a {{floating bearing arrangement|schwimmende Lagerung}} the shaft has a defined axial play of approx. 0.5 … 1 mm. It is simple and cheap, but not suitable for alternating axial loads.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$bearings$q$, $q$mc$q$, $q$Welche Berührung haben Rollenlager zwischen {{Wälzkörper|rolling element}} und Laufbahn?$q$, $q$What kind of contact do roller bearings have between {{rolling element|Wälzkörper}} and raceway?$q$, null, null, $q$[{"de": "{{Punktberührung|point contact}}", "en": "{{Point contact|Punktberührung}}"}, {"de": "{{Linienberührung|line contact}}", "en": "{{Line contact|Linienberührung}}"}, {"de": "Flächenberührung", "en": "Surface contact"}, {"de": "Keine, nur Schmierfilm", "en": "None, only a lubricant film"}]$q$::jsonb, $q$1$q$::jsonb, $q$Rollen haben {{Linienberührung|line contact}} und tragen deshalb radial mehr als vergleichbare Kugellager. Kugeln haben {{Punktberührung|point contact}}.$q$, $q$Rollers have {{line contact|Linienberührung}} and therefore carry more radial load than comparable ball bearings. Balls have {{point contact|Punktberührung}}.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welche Verzahnung (Verlauf der {{Flankenlinie|flank line}}) ist dargestellt? (Seitenansicht zweier Stirnräder)$q$, $q$Which gearing (course of the {{flank line|Flankenlinie}}) is shown? (side view of two spur gears)$q$, $q$img/zahnrad_gerade.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Geradverzahnung|straight-cut gearing}}", "en": "{{straight-cut gearing|Geradverzahnung}}"}, {"de": "{{Schrägverzahnung|helical gearing}}", "en": "{{helical gearing|Schrägverzahnung}}"}, {"de": "{{Pfeilverzahnung|herringbone gearing}}", "en": "{{herringbone gearing|Pfeilverzahnung}}"}, {"de": "{{Doppelschrägverzahnung|double helical gearing}}", "en": "{{double helical gearing|Doppelschrägverzahnung}}"}]$q$::jsonb, $q$0$q$::jsonb, $q${{Geradverzahnung|straight-cut gearing}}: Die Flankenlinien verlaufen parallel zur Radachse. Sie ist robust und einfach herzustellen, läuft aber lauter, weil die Zähne stoßartig eingreifen.$q$, $q${{Straight-cut gearing|Geradverzahnung}}: the flank lines run parallel to the gear axis. It is robust and easy to make, but noisier because the teeth engage abruptly.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welche Verzahnung (Verlauf der {{Flankenlinie|flank line}}) ist dargestellt? (Seitenansicht zweier Stirnräder)$q$, $q$Which gearing (course of the {{flank line|Flankenlinie}}) is shown? (side view of two spur gears)$q$, $q$img/zahnrad_schraeg.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Geradverzahnung|straight-cut gearing}}", "en": "{{straight-cut gearing|Geradverzahnung}}"}, {"de": "{{Schrägverzahnung|helical gearing}}", "en": "{{helical gearing|Schrägverzahnung}}"}, {"de": "{{Pfeilverzahnung|herringbone gearing}}", "en": "{{herringbone gearing|Pfeilverzahnung}}"}, {"de": "{{Doppelschrägverzahnung|double helical gearing}}", "en": "{{double helical gearing|Doppelschrägverzahnung}}"}]$q$::jsonb, $q$1$q$::jsonb, $q${{Schrägverzahnung|helical gearing}}: Die Flankenlinien liegen schräg (Schrägungswinkel β). Die Zähne greifen allmählich ein, das Getriebe läuft ruhiger und trägt mehr, erzeugt aber eine {{Axialkraft|axial force}}.$q$, $q${{Helical gearing|Schrägverzahnung}}: the flank lines are inclined (helix angle β). The teeth engage gradually, so the gearbox runs more smoothly and carries more load, but it creates an {{axial force|Axialkraft}}.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welche Verzahnung (Verlauf der {{Flankenlinie|flank line}}) ist dargestellt? (Seitenansicht zweier Stirnräder)$q$, $q$Which gearing (course of the {{flank line|Flankenlinie}}) is shown? (side view of two spur gears)$q$, $q$img/zahnrad_pfeil.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Geradverzahnung|straight-cut gearing}}", "en": "{{straight-cut gearing|Geradverzahnung}}"}, {"de": "{{Schrägverzahnung|helical gearing}}", "en": "{{helical gearing|Schrägverzahnung}}"}, {"de": "{{Pfeilverzahnung|herringbone gearing}}", "en": "{{herringbone gearing|Pfeilverzahnung}}"}, {"de": "{{Doppelschrägverzahnung|double helical gearing}}", "en": "{{double helical gearing|Doppelschrägverzahnung}}"}]$q$::jsonb, $q$2$q$::jsonb, $q${{Pfeilverzahnung|herringbone gearing}}: zwei gegensinnig schräge Zahnreihen ohne Zwischennut. Die Axialkräfte heben sich gegenseitig auf.$q$, $q${{Herringbone gearing|Pfeilverzahnung}}: two oppositely inclined rows of teeth without a groove between them. The axial forces cancel each other out.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welche Verzahnung (Verlauf der {{Flankenlinie|flank line}}) ist dargestellt? (Seitenansicht zweier Stirnräder)$q$, $q$Which gearing (course of the {{flank line|Flankenlinie}}) is shown? (side view of two spur gears)$q$, $q$img/zahnrad_doppelschraeg.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Geradverzahnung|straight-cut gearing}}", "en": "{{straight-cut gearing|Geradverzahnung}}"}, {"de": "{{Schrägverzahnung|helical gearing}}", "en": "{{helical gearing|Schrägverzahnung}}"}, {"de": "{{Pfeilverzahnung|herringbone gearing}}", "en": "{{herringbone gearing|Pfeilverzahnung}}"}, {"de": "{{Doppelschrägverzahnung|double helical gearing}}", "en": "{{double helical gearing|Doppelschrägverzahnung}}"}]$q$::jsonb, $q$3$q$::jsonb, $q${{Doppelschrägverzahnung|double helical gearing}}: zwei gegensinnig schräge Zahnreihen mit einer Nut dazwischen (Werkzeugauslauf). Auch hier heben sich die Axialkräfte auf.$q$, $q${{Double helical gearing|Doppelschrägverzahnung}}: two oppositely inclined rows of teeth with a groove between them (tool runout). Here too the axial forces cancel out.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welche Getriebeart ist dargestellt?$q$, $q$Which type of gear drive is shown?$q$, $q$img/zahnrad_kegelrad.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Stirnradgetriebe|spur gearbox}}", "en": "{{spur gearbox|Stirnradgetriebe}}"}, {"de": "{{Kegelradgetriebe|bevel gearbox}}", "en": "{{bevel gearbox|Kegelradgetriebe}}"}, {"de": "{{Schneckengetriebe|worm gearbox}}", "en": "{{worm gearbox|Schneckengetriebe}}"}, {"de": "Getriebe mit {{Zahnstange|rack}}", "en": "{{Rack|Zahnstange}} and pinion drive"}]$q$::jsonb, $q$1$q$::jsonb, $q${{Kegelradgetriebe|bevel gearbox}}: Die Achsen schneiden sich (meist unter 90°), die Räder sind kegelförmig. Die gestrichelte Linie zeigt die gemeinsame Kegelmantellinie zur Kegelspitze.$q$, $q${{Bevel gearbox|Kegelradgetriebe}}: the axes intersect (usually at 90°) and the gears are conical. The dashed line marks the common cone generator leading to the cone apex.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welche Getriebeart ist dargestellt?$q$, $q$Which type of gear drive is shown?$q$, $q$img/zahnrad_schnecke.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Stirnradgetriebe|spur gearbox}}", "en": "{{spur gearbox|Stirnradgetriebe}}"}, {"de": "{{Kegelradgetriebe|bevel gearbox}}", "en": "{{bevel gearbox|Kegelradgetriebe}}"}, {"de": "{{Schneckengetriebe|worm gearbox}}", "en": "{{worm gearbox|Schneckengetriebe}}"}, {"de": "Getriebe mit {{Zahnstange|rack}}", "en": "{{Rack|Zahnstange}} and pinion drive"}]$q$::jsonb, $q$2$q$::jsonb, $q${{Schneckengetriebe|worm gearbox}}: Die Achsen von Schnecke und Schneckenrad kreuzen sich, ohne sich zu schneiden. Damit sind große Übersetzungen in einer Stufe möglich.$q$, $q${{Worm gearbox|Schneckengetriebe}}: the axes of worm and worm wheel cross without intersecting. This allows large transmission ratios in a single stage.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Welche Getriebeart ist dargestellt?$q$, $q$Which type of gear drive is shown?$q$, $q$img/zahnrad_zahnstange.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Stirnradgetriebe|spur gearbox}}", "en": "{{spur gearbox|Stirnradgetriebe}}"}, {"de": "{{Kegelradgetriebe|bevel gearbox}}", "en": "{{bevel gearbox|Kegelradgetriebe}}"}, {"de": "{{Schneckengetriebe|worm gearbox}}", "en": "{{worm gearbox|Schneckengetriebe}}"}, {"de": "Getriebe mit {{Zahnstange|rack}}", "en": "{{Rack|Zahnstange}} and pinion drive"}]$q$::jsonb, $q$3$q$::jsonb, $q$Getriebe mit {{Zahnstange|rack}} und Ritzel: Es wandelt eine Drehbewegung in eine geradlinige Bewegung um oder umgekehrt.$q$, $q${{Rack|Zahnstange}} and pinion drive: it converts rotation into linear motion or vice versa.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$img$q$, $q$Wie heißt das große, innenverzahnte Rad in dieser Abbildung?$q$, $q$What is the large internally toothed gear in this figure called?$q$, $q$img/zahnrad_hohlrad.svg$q$, $q$Eigene Darstellung, Lehrstuhl FMT$q$, $q$[{"de": "{{Ritzel|pinion}}", "en": "{{Pinion|Ritzel}}"}, {"de": "{{Hohlrad|internal gear}}", "en": "{{Internal gear|Hohlrad}}"}, {"de": "Schneckenrad", "en": "Worm wheel"}, {"de": "{{Zahnstange|rack}}", "en": "{{Rack|Zahnstange}}"}]$q$::jsonb, $q$1$q$::jsonb, $q$Ein innenverzahntes Rad heißt {{Hohlrad|internal gear}}. Mit einem außenverzahnten {{Ritzel|pinion}} bildet es ein Innen-Stirnradgetriebe mit parallelen Achsen und gleicher Drehrichtung.$q$, $q$An internally toothed gear is called an {{internal gear|Hohlrad}}. Together with an external {{pinion|Ritzel}} it forms an internal spur gear drive with parallel axes and the same direction of rotation.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Welcher Nachteil hat die {{Schrägverzahnung|helical gearing}} gegenüber der {{Geradverzahnung|straight-cut gearing}}?$q$, $q$What is a disadvantage of {{helical gearing|Schrägverzahnung}} compared to {{straight-cut gearing|Geradverzahnung}}?$q$, null, null, $q$[{"de": "Lauterer Lauf", "en": "Noisier operation"}, {"de": "Geringere Tragfähigkeit", "en": "Lower load capacity"}, {"de": "Zusätzliche {{Axialkraft|axial force}}", "en": "Additional {{axial force|Axialkraft}}"}, {"de": "Kleinere {{Profilüberdeckung|contact ratio}}", "en": "Smaller {{contact ratio|Profilüberdeckung}}"}]$q$::jsonb, $q$2$q$::jsonb, $q$Schrägverzahnung läuft ruhiger, trägt mehr und hat eine größere Überdeckung. Sie erzeugt aber eine {{Axialkraft|axial force}}, die die Lager aufnehmen müssen.$q$, $q$Helical gearing runs more smoothly, carries more load and has a larger contact ratio. However, it creates an {{axial force|Axialkraft}} that the bearings must absorb.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Warum verwendet man {{Pfeilverzahnung|herringbone gearing}} oder {{Doppelschrägverzahnung|double helical gearing}}?$q$, $q$Why is {{herringbone gearing|Pfeilverzahnung}} or {{double helical gearing|Doppelschrägverzahnung}} used?$q$, null, null, $q$[{"de": "Weil sie einfacher herzustellen ist", "en": "Because it is easier to manufacture"}, {"de": "Weil sich die Axialkräfte der beiden Zahnhälften aufheben", "en": "Because the axial forces of both tooth halves cancel out"}, {"de": "Weil sie eine größere Übersetzung erlaubt", "en": "Because it allows a larger transmission ratio"}, {"de": "Weil kein Schmierstoff nötig ist", "en": "Because no lubricant is needed"}]$q$::jsonb, $q$1$q$::jsonb, $q$Die beiden gegensinnig schrägen Hälften erzeugen entgegengesetzte Axialkräfte. Man nutzt also die Laufruhe der Schrägverzahnung ohne Axiallast auf die Lager.$q$, $q$The two oppositely inclined halves produce opposite axial forces. You get the smooth running of helical gearing without axial load on the bearings.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$match$q$, $q$Ordne jedem Getriebe die Lage seiner Achsen bzw. seine Funktion zu.$q$, $q$Match each gear drive to its axis arrangement or function.$q$, null, null, $q${"left": [{"de": "{{Stirnradgetriebe|spur gearbox}}", "en": "{{spur gearbox|Stirnradgetriebe}}"}, {"de": "{{Kegelradgetriebe|bevel gearbox}}", "en": "{{bevel gearbox|Kegelradgetriebe}}"}, {"de": "{{Schneckengetriebe|worm gearbox}}", "en": "{{worm gearbox|Schneckengetriebe}}"}, {"de": "{{Zahnstange|rack}} und {{Ritzel|pinion}}", "en": "{{Rack|Zahnstange}} and {{pinion|Ritzel}}"}], "right": [{"de": "Parallele Achsen", "en": "Parallel axes"}, {"de": "Sich schneidende Achsen", "en": "Intersecting axes"}, {"de": "Gekreuzte Achsen, große Übersetzung", "en": "Crossed axes, large transmission ratio"}, {"de": "Drehbewegung ↔ Längsbewegung", "en": "Rotation ↔ linear motion"}]}$q$::jsonb, null, $q$Stirnrad: parallele Achsen. Kegelrad: sich schneidende Achsen. Schnecke (und Hypoid): gekreuzte Achsen. Zahnstange: wandelt Dreh- in Längsbewegung.$q$, $q$Spur gear: parallel axes. Bevel gear: intersecting axes. Worm (and hypoid): crossed axes. Rack: converts rotation into linear motion.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Welcher {{Eingriffswinkel|pressure angle}} α ist nach DIN 867 genormt?$q$, $q$Which {{pressure angle|Eingriffswinkel}} α is standardized according to DIN 867?$q$, null, null, $q$[{"de": "14,5°", "en": "14.5°"}, {"de": "15°", "en": "15°"}, {"de": "20°", "en": "20°"}, {"de": "30°", "en": "30°"}]$q$::jsonb, $q$2$q$::jsonb, $q$Das Bezugsprofil nach DIN 867 hat einen {{Eingriffswinkel|pressure angle}} von α = 20°.$q$, $q$The reference profile according to DIN 867 has a {{pressure angle|Eingriffswinkel}} of α = 20°.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Wie hängen {{Teilkreis|pitch circle}}-Durchmesser d, {{Modul|module}} m und {{Zähnezahl|number of teeth}} z zusammen?$q$, $q$How are {{pitch circle|Teilkreis}} diameter d, {{module|Modul}} m and {{number of teeth|Zähnezahl}} z related?$q$, null, null, $q$[{"de": "d = m · z", "en": "d = m · z"}, {"de": "d = m / z", "en": "d = m / z"}, {"de": "d = z / m", "en": "d = z / m"}, {"de": "d = π · z / m", "en": "d = π · z / m"}]$q$::jsonb, $q$0$q$::jsonb, $q$d = m · z. Der Modul ist das Maß für die Zahngröße (m = p/π). Bei gleicher Zähnezahl hat ein größerer Modul also einen größeren Durchmesser.$q$, $q$d = m · z. The module is the measure of tooth size (m = p/π), so with the same number of teeth a larger module gives a larger diameter.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Wie berechnet man die {{Übersetzung|transmission ratio}} i einer Zahnradstufe (1 = treibendes Rad, 2 = getriebenes Rad)?$q$, $q$How is the {{transmission ratio|Übersetzung}} i of a gear stage calculated (1 = driving gear, 2 = driven gear)?$q$, null, null, $q$[{"de": "i = z₁ / z₂ = n₂ / n₁", "en": "i = z₁ / z₂ = n₂ / n₁"}, {"de": "i = z₂ / z₁ = n₁ / n₂", "en": "i = z₂ / z₁ = n₁ / n₂"}, {"de": "i = z₁ · z₂", "en": "i = z₁ · z₂"}, {"de": "i = n₁ · n₂", "en": "i = n₁ · n₂"}]$q$::jsonb, $q$1$q$::jsonb, $q$i = n₁ / n₂ = z₂ / z₁. Treibt ein kleines Ritzel ein großes Rad, ist i > 1: Die Drehzahl sinkt, das Moment steigt.$q$, $q$i = n₁ / n₂ = z₂ / z₁. If a small pinion drives a large gear, i > 1: speed decreases and torque increases.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Warum hat sich die {{Evolventenverzahnung|involute gearing}} im Maschinenbau durchgesetzt?$q$, $q$Why has {{involute gearing|Evolventenverzahnung}} become established in mechanical engineering?$q$, null, null, $q$[{"de": "Sie rollt ganz ohne Gleiten ab", "en": "It rolls without any sliding"}, {"de": "Sie ist unempfindlich gegen Änderungen des {{Achsabstand|center distance}}s und günstig herzustellen", "en": "It is insensitive to changes in {{center distance|Achsabstand}} and cheap to manufacture"}, {"de": "Sie braucht keine Schmierung", "en": "It needs no lubrication"}, {"de": "Sie hat eine veränderliche Übersetzung", "en": "It has a variable transmission ratio"}]$q$::jsonb, $q$1$q$::jsonb, $q$Die Evolvente ist günstig herzustellen (gerade Werkzeugflanken), hält die Übersetzung konstant und reagiert kaum auf Achsabstandsänderungen. Ein gewisses Gleiten (Verschleiß) bleibt.$q$, $q$The involute is cheap to manufacture (straight tool flanks), keeps the transmission ratio constant and is insensitive to center distance changes. Some sliding (wear) remains.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$tf$q$, $q$Die abgebildete {{Zykloidenverzahnung|cycloidal gearing}} (Flanken entstehen durch Abrollen von Rollkreisen auf dem Grundkreis) ist unempfindlich gegen Änderungen des {{Achsabstand|center distance}}s.$q$, $q$The {{cycloidal gearing|Zykloidenverzahnung}} shown (flanks generated by rolling circles on the base circle) is insensitive to changes in {{center distance|Achsabstand}}.$q$, $q$img/foto_zykloide.jpg$q$, $q$YouTube, www.youtube.com/watch?v=c0LSoBxfOq0 · Skript FME, Folie 27$q$, null, $q$false$q$::jsonb, $q$Falsch. Die Flanken entstehen durch Abrollen eines Rollkreises außen (Epizykloide) und innen (Hypozykloide) auf dem Grundkreis. Die Verzahnung rollt fast ohne Gleiten ab, reagiert aber empfindlich auf Achsabstandsänderungen. Man findet sie z. B. in Feinwerktechnik und Uhren.$q$, $q$False. The flanks are generated by a rolling circle rolling outside (epicycloid) and inside (hypocycloid) the base circle. The gearing rolls with almost no sliding but is sensitive to center distance changes. It is used e.g. in precision devices and clocks.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Welchen Mindestwert muss die {{Profilüberdeckung|contact ratio}} εα haben?$q$, $q$What minimum value must the {{contact ratio|Profilüberdeckung}} εα have?$q$, null, null, $q$[{"de": "0,5", "en": "0.5"}, {"de": "1", "en": "1"}, {"de": "2", "en": "2"}, {"de": "π", "en": "π"}]$q$::jsonb, $q$1$q$::jsonb, $q$εα ≥ 1, damit in jeder Stellung mindestens ein Zahnpaar im Eingriff ist. Bei εα < 1 entsteht Spiel und das Getriebe klappert bei Drehrichtungswechsel.$q$, $q$εα ≥ 1, so that at least one tooth pair is in mesh at every position. With εα < 1 backlash occurs and the gearbox rattles when the direction of rotation changes.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Welcher Punkt ist KEIN Grund für eine {{Profilverschiebung|profile shift}}?$q$, $q$Which of these is NOT a reason for {{profile shift|Profilverschiebung}}?$q$, null, null, $q$[{"de": "Anpassung an einen vorgegebenen {{Achsabstand|center distance}}", "en": "Adapting to a given {{center distance|Achsabstand}}"}, {"de": "Erhöhung der Tragfähigkeit am {{Zahnfuß|tooth root}}", "en": "Increasing the load capacity at the {{tooth root|Zahnfuß}}"}, {"de": "Vermeidung von {{Unterschnitt|undercut}}", "en": "Avoiding {{undercut|Unterschnitt}}"}, {"de": "Änderung der {{Übersetzung|transmission ratio}}", "en": "Changing the {{transmission ratio|Übersetzung}}"}]$q$::jsonb, $q$3$q$::jsonb, $q$Die Profilverschiebung nutzt nur einen anderen Bereich derselben Evolvente. Die Übersetzung bleibt deshalb unverändert.$q$, $q$Profile shift only uses a different part of the same involute. The transmission ratio therefore stays the same.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$tf$q$, $q$Eine positive {{Profilverschiebung|profile shift}} (V-Plus) verstärkt den {{Zahnfuß|tooth root}} und schwächt den {{Zahnkopf|tooth tip}}.$q$, $q$A positive {{profile shift|Profilverschiebung}} (V-plus) strengthens the {{tooth root|Zahnfuß}} and weakens the {{tooth tip|Zahnkopf}}.$q$, null, null, null, $q$true$q$::jsonb, $q$Richtig. Der Zahnfuß wird dicker, der Kopf dünner. Grenze ist ein zu spitzer Zahnkopf; bei negativer Verschiebung droht Unterschnitt.$q$, $q$Correct. The root gets thicker and the tip thinner. The limit is an overly pointed tip; negative shift risks undercut.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$An den Zahnflanken entstehen durch Ermüdung kleine Materialausbrüche. Wie heißt dieses Schadensbild?$q$, $q$Small material break-outs appear on the tooth flanks due to fatigue. What is this failure called?$q$, null, null, $q$[{"de": "{{Fressen|scuffing}}", "en": "{{Scuffing|Fressen}}"}, {"de": "{{Zahnfußbruch|tooth root breakage}}", "en": "{{Tooth root breakage|Zahnfußbruch}}"}, {"de": "{{Grübchenbildung|pitting}}", "en": "{{Pitting|Grübchenbildung}}"}, {"de": "{{Graufleckigkeit|micropitting}}", "en": "{{Micropitting|Graufleckigkeit}}"}]$q$::jsonb, $q$2$q$::jsonb, $q$Grübchen (Pitting) entstehen durch hohe wechselnde Pressungen an der Flanke (Flankentragfähigkeit, DIN 3990 / ISO 6336).$q$, $q$Pitting is caused by high alternating contact pressures on the flank (flank load capacity, DIN 3990 / ISO 6336).$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Die Zahnflanken verschweißen kurzzeitig und reißen wieder auf, weil der Schmierfilm thermisch versagt. Welches Schadensbild ist das?$q$, $q$The tooth flanks briefly weld together and tear apart because the lubricant film fails thermally. Which failure is this?$q$, null, null, $q$[{"de": "{{Fressen|scuffing}}", "en": "{{Scuffing|Fressen}}"}, {"de": "{{Grübchenbildung|pitting}}", "en": "{{Pitting|Grübchenbildung}}"}, {"de": "{{Graufleckigkeit|micropitting}}", "en": "{{Micropitting|Graufleckigkeit}}"}, {"de": "Verschleiß durch Unterschnitt", "en": "Wear due to undercut"}]$q$::jsonb, $q$0$q$::jsonb, $q$Beim Fressen versagen Schmierstoff und Schutzschichten durch zu hohe Temperatur im Kontakt. Die Flanken werden großflächig zerstört. Gleiche Härte beider Räder bei ungehärteten Flanken fördert Fressen.$q$, $q$During scuffing the lubricant and protective layers fail due to excessive contact temperature. The flanks are destroyed over large areas. Equal hardness of both gears with unhardened flanks promotes scuffing.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$match$q$, $q$Ordne die Zahnradschäden ihrer Beschreibung zu.$q$, $q$Match the gear failures to their description.$q$, null, null, $q${"left": [{"de": "{{Grübchenbildung|pitting}}", "en": "{{Pitting|Grübchenbildung}}"}, {"de": "{{Zahnfußbruch|tooth root breakage}}", "en": "{{Tooth root breakage|Zahnfußbruch}}"}, {"de": "{{Fressen|scuffing}}", "en": "{{Scuffing|Fressen}}"}, {"de": "{{Graufleckigkeit|micropitting}}", "en": "{{Micropitting|Graufleckigkeit}}"}], "right": [{"de": "Ermüdungsausbrüche auf der Flanke", "en": "Fatigue break-outs on the flank"}, {"de": "Riss im Zahnfuß, Zahn bricht ab", "en": "Crack at the tooth root, tooth breaks off"}, {"de": "Verschweißen und Aufreißen der Flanken", "en": "Flanks weld together and tear apart"}, {"de": "Mikroermüdung, grau schimmernde Flächen", "en": "Micro-fatigue, grey shaded areas"}]}$q$::jsonb, null, $q$Die vier Hauptschadensarten aus der Vorlesung: Grübchen (Flanke), Zahnfußbruch (Fuß), Fressen (Schmierfilmversagen), Graufleckigkeit (Mikroermüdung).$q$, $q$The four main failure types from the lecture: pitting (flank), tooth root breakage (root), scuffing (lubricant film failure), micropitting (micro-fatigue).$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Wie ergibt sich die Gesamtübersetzung eines mehrstufigen Getriebes?$q$, $q$How is the total transmission ratio of a multi-stage gearbox obtained?$q$, null, null, $q$[{"de": "i_ges = i₁ + i₂ + …", "en": "i_total = i₁ + i₂ + …"}, {"de": "i_ges = i₁ · i₂ · …", "en": "i_total = i₁ · i₂ · …"}, {"de": "i_ges = größte Einzelübersetzung", "en": "i_total = largest single ratio"}, {"de": "i_ges = (i₁ + i₂) / 2", "en": "i_total = (i₁ + i₂) / 2"}]$q$::jsonb, $q$1$q$::jsonb, $q$Die Einzelübersetzungen werden multipliziert. Dasselbe gilt für die Wirkungsgrade: η_ges = η₁ · η₂ · …$q$, $q$The individual ratios are multiplied. The same applies to efficiencies: η_total = η₁ · η₂ · …$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Wie berechnet man das Abtriebsmoment T₂ aus dem Antriebsmoment T₁, der {{Übersetzung|transmission ratio}} i und dem {{Wirkungsgrad|efficiency}} η?$q$, $q$How is the output torque T₂ calculated from the input torque T₁, the {{transmission ratio|Übersetzung}} i and the {{efficiency|Wirkungsgrad}} η?$q$, null, null, $q$[{"de": "T₂ = η · i · T₁", "en": "T₂ = η · i · T₁"}, {"de": "T₂ = T₁ / (η · i)", "en": "T₂ = T₁ / (η · i)"}, {"de": "T₂ = η · T₁ / i", "en": "T₂ = η · T₁ / i"}, {"de": "T₂ = i · T₁ / η", "en": "T₂ = i · T₁ / η"}]$q$::jsonb, $q$0$q$::jsonb, $q$T₂ = η · i · T₁. Aus P = T · ω folgt: Wird die Drehzahl um i reduziert, steigt das Moment um i; der Wirkungsgrad η < 1 mindert es etwas.$q$, $q$T₂ = η · i · T₁. From P = T · ω: if speed is reduced by i, torque rises by i; the efficiency η < 1 reduces it somewhat.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Wie berechnet man die {{Tangentialkraft|tangential force}} Ft am Zahnrad aus Drehmoment T und {{Teilkreis|pitch circle}}-Durchmesser d?$q$, $q$How is the {{tangential force|Tangentialkraft}} Ft on a gear calculated from torque T and {{pitch circle|Teilkreis}} diameter d?$q$, null, null, $q$[{"de": "Ft = T · d", "en": "Ft = T · d"}, {"de": "Ft = 2 · T / d", "en": "Ft = 2 · T / d"}, {"de": "Ft = T / (2 · d)", "en": "Ft = T / (2 · d)"}, {"de": "Ft = d / T", "en": "Ft = d / T"}]$q$::jsonb, $q$1$q$::jsonb, $q$Ft = T / r = 2 · T / d. Die Radialkraft folgt daraus mit Fr = Ft · tan α.$q$, $q$Ft = T / r = 2 · T / d. The radial force follows as Fr = Ft · tan α.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$tf$q$, $q$Das {{Ritzel|pinion}} sollte den festeren Werkstoff bekommen, weil es mehr Lastwechsel erfährt als das große Rad.$q$, $q$The {{pinion|Ritzel}} should get the stronger material because it experiences more load cycles than the large gear.$q$, null, null, null, $q$true$q$::jsonb, $q$Richtig. Das kleine Rad dreht schneller und jeder Zahn wird öfter belastet. Werkstoff und Wärmebehandlung trotzdem nur so hochwertig wie nötig wählen.$q$, $q$Correct. The small gear turns faster and each tooth is loaded more often. Still, choose material and heat treatment only as high-grade as necessary.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$tf$q$, $q$Zahnradgetriebe bieten von sich aus einen Überlastschutz.$q$, $q$Gear drives provide overload protection by themselves.$q$, null, null, null, $q$false$q$::jsonb, $q$Falsch. Zahnradgetriebe übertragen formschlüssig und schlupffrei. Deshalb haben sie keinen Überlastschutz; dafür braucht man z. B. eine Rutschkupplung.$q$, $q$False. Gear drives transmit by form fit and without slip. That is why they have no overload protection; you need e.g. a slip clutch for that.$q$);
insert into public.questions (topic_id, qtype, prompt_de, prompt_en, image, image_source, options, correct, explanation_de, explanation_en) values ($q$gears$q$, $q$mc$q$, $q$Ab welcher {{Zähnezahl|number of teeth}} tritt bei geradverzahnten Stirnrädern (ohne Profilverschiebung) theoretisch kein {{Unterschnitt|undercut}} mehr auf?$q$, $q$From which {{number of teeth|Zähnezahl}} does {{undercut|Unterschnitt}} theoretically no longer occur on straight-cut spur gears (without profile shift)?$q$, null, null, $q$[{"de": "z ≥ 7", "en": "z ≥ 7"}, {"de": "z ≥ 14", "en": "z ≥ 14"}, {"de": "z ≥ 17", "en": "z ≥ 17"}, {"de": "z ≥ 25", "en": "z ≥ 25"}]$q$::jsonb, $q$2$q$::jsonb, $q$Die theoretische Grenzzähnezahl ist 17, praktisch genügen etwa 14. Bei weniger Zähnen hilft eine positive Profilverschiebung.$q$, $q$The theoretical limit is 17 teeth; in practice about 14 is enough. With fewer teeth, a positive profile shift helps.$q$);
